#' Uncertainties from Certified Values
#'
#' 
#' @param data .
#' @param x .
#' @param c .
#' @param mpem .
#' @param m .
#' @param uwcal .
#' @param k .
#' @param cwcal .
#' @param a .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$ucv} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$empu} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$ewu} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$eiscu} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$ruchar} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
UCV <- function(
    data,
    x,
    c,
    mpem,
    m,
    uwcal,
    k = 2,
    cwcal,
    a = "0.05") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("UCV requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL))


    options <- UCVOptions$new(
        x = x,
        c = c,
        mpem = mpem,
        m = m,
        uwcal = uwcal,
        k = k,
        cwcal = cwcal,
        a = a)

    analysis <- UCVClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

